from typing import *
from collections import *

def monotonic(l: List[int]) -> bool:
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    direction = None
    for i in range(1, len(l)):
        if direction is None:
            if l[i] > l[i-1]:
                direction = 'increasing'
            elif l[i] < l[i-1]:
                direction = 'decreasing'
        else:
            if direction == 'increasing' and l[i] < l[i-1]:
                return False
            elif direction == 'decreasing' and l[i] > l[i-1]:
                return False

    return True
