from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(x, y, path, steps):
        if steps == k:
            return path

        min_path = []
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = dfs(nx, ny, path + [grid[nx][ny]], steps + 1)
                if not min_path or new_path < min_path:
                    min_path = new_path

        return min_path

    min_path = None
    for i in range(n):
        for j in range(n):
            result = dfs(i, j, [grid[i][j]], 1)
            if not min_path or result < min_path:
                min_path = result

    return min_path
