```python
def power(a, b):
    """
    Calculate the value of 'a' raised to the power 'b'.

    Args:
    a (int): The base number.
    b (int): The exponent.

    Returns:
    int: The result of 'a' raised to the power 'b'.
    """
    if b == 0:
        return 1
    elif b < 0:
        return 1 / power(a, -b)
    else:
        result = 1
        for _ in range(b):
            result *= a
        return result
