from typing import List

def max_sum(arr: List[int]) -> int:
    n = len(arr)

    # Initialize dp arrays
    inc = [arr[i] for i in range(n)]
    dec = [arr[i] for i in range(n)]

    # Fill up the inc array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill up the dec array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find the maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum
