import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Convert the input list to an array for sorting
        Integer[] arr = new Integer[l.size()];
        for (int i = 0; i < l.size(); i++) {
            arr[i] = l.get(i);
        }

        // Sort the array elements at indices divisible by 3
        Arrays.sort(arr, 0, arr.length / 3);

        // Create a new list to store the result
        List<Integer> result = new ArrayList<>();

        // Copy elements from the original list to the result list
        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) {
                result.add(arr[i / 3]);
            } else {
                result.add(l.get(i));
            }
        }

        return result;
    }
}
