import java.math.BigInteger;

public class Solution {
    public int primeFib(int n) {
        BigInteger[] fib = new BigInteger[2];
        fib[0] = BigInteger.ONE;
        fib[1] = BigInteger.ONE;

        while (true) {
            BigInteger nextFib = fib[0].add(fib[1]);
            if (isPrime(nextFib)) {
                n--;
            }
            if (n == 0) {
                return nextFib.intValue();
            }
            fib[0] = fib[1];
            fib[1] = nextFib;
        }
    }

    private boolean isPrime(BigInteger num) {
        if (num.compareTo(BigInteger.ZERO) <= 0) {
            return false;
        }
        if (num.equals(BigInteger.ONE)) {
            return false;
        }
        if (num.equals(BigInteger.TWO)) {
            return true;
        }
        if (num.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO)) {
            return false;
        }
        BigInteger sqrtNum = num.sqrt();
        for (BigInteger i = BigInteger.valueOf(3); i.compareTo(sqrtNum) <= 0; i = i.add(BigInteger.valueOf(2))) {
            if (num.mod(i).equals(BigInteger.ZERO)) {
                return false;
            }
        }
        return true;
    }
}
