import java.util.*;
import java.lang.*;

class Solution {
    public int largestPrimeFactor(int n) {
        // Helper function to check if a number is prime
        boolean isPrime(int k) {
            if (k < 2) {
                return false;
            }
            for (int i = 2; i * i <= k; i++) {
                if (k % i == 0) {
                    return false;
                }
            }
            return true;
        }

        int largest = 1;
        // Iterate from 2 to n-1 to find the largest prime factor
        for (int j = 2; j <= n; j++) {
            if (n % j == 0 && isPrime(j)) {
                largest = Math.max(largest, j);
            }
        }
        return largest;
    }
}
