import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> pluck(List<Integer> arr) {
        if (arr.isEmpty()) return new ArrayList<>();

        List<Integer> evens = new ArrayList<>();
        for (int i = 0; i < arr.size(); i++) {
            if (arr.get(i) % 2 == 0) {
                evens.add(arr.get(i));
            }
        }

        if (evens.isEmpty()) return new ArrayList<>();

        int minIndex = evens.indexOf(Collections.min(evens));
        return Arrays.asList(Collections.min(evens), minIndex);
    }
}
