import java.util.*;
import java.lang.*;

class Solution {
    public boolean iscube(int a) {
        // Convert the input to its absolute value
        a = Math.abs(a);

        // Calculate the cube root of the absolute value
        double cubeRoot = Math.cbrt(a);

        // Round the cube root to the nearest integer
        int roundedCubeRoot = (int)Math.round(cubeRoot);

        // Check if the cubed value of the rounded cube root equals the original input
        return roundedCubeRoot * roundedCubeRoot * roundedCubeRoot == a;
    }
}
