import java.util.*;
import java.lang.*;

class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();

        // Find all occurrences of x in the list
        for (int i = 0; i < lst.size(); i++) {
            for (int j = 0; j < lst.get(i).size(); j++) {
                if (lst.get(i).get(j) == x) {
                    result.add(Arrays.asList(i, j));
                }
            }
        }

        // Sort the results first by row in ascending order, then by column in descending order
        Collections.sort(result, Comparator.comparingInt(row -> row.get(0)).thenComparingInt(col -> col.get(1)).reversed());

        return result;
    }
}
