import java.util.*;
import java.lang.*;

class Solution {
    public String encode(String message) {
        // Define vowels and their replacements
        Map<Character, Character> vowelsReplace = new HashMap<>();
        vowelsReplace.put('a', 'c');
        vowelsReplace.put('e', 'g');
        vowelsReplace.put('i', 'k');
        vowelsReplace.put('o', 'q');
        vowelsReplace.put('u', 'w');
        vowelsReplace.put('A', 'C');
        vowelsReplace.put('E', 'G');
        vowelsReplace.put('I', 'K');
        vowelsReplace.put('O', 'Q');
        vowelsReplace.put('U', 'W');

        // Swap case of the message
        StringBuilder encodedMessage = new StringBuilder();
        for (char c : message.toCharArray()) {
            if (Character.isLetter(c)) {
                char swappedCaseChar = Character.isUpperCase(c) ? Character.toLowerCase(c) : Character.toUpperCase(c);
                encodedMessage.append(vowelsReplace.containsKey(swappedCaseChar) ? vowelsReplace.get(swappedCaseChar) : swappedCaseChar);
            } else {
                encodedMessage.append(c);
            }
        }

        return encodedMessage.toString();
    }
}
