import java.util.*;
import java.lang.*;

class Solution {
    public int countNums(List<Integer> arr) {
        // Helper function to calculate the sum of digits of a number
        private int digitsSum(int n) {
            int neg = 1;
            if (n < 0) {
                n = -1 * n;
                neg = -1;
            }
            List<Integer> digits = new ArrayList<>();
            while (n != 0) {
                digits.add(n % 10);
                n /= 10;
            }
            digits.set(0, digits.get(0) * neg);
            return digits.stream().mapToInt(Integer::intValue).sum();
        }

        // Count numbers with positive digit sums
        return (int) arr.stream()
                         .filter(num -> digitsSum(num) > 0)
                         .count();
    }
}
