import java.util.List;

class Solution {
    public int minSubArraySum(List<Integer> nums) {
        int max_sum = 0;
        int s = 0;
        for (int num : nums) {
            s += -num;
            if (s < 0) {
                s = 0;
            }
            max_sum = Math.max(s, max_sum);
        }
        if (max_sum == 0) {
            max_sum = Collections.min(nums);
        }
        return -max_sum;
    }
}
