import java.util.ArrayList;
import java.util.Arrays;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int val = n * n + 1;

        // Find the smallest value in the first row
        for (int j = 0; j < n; j++) {
            if (grid.get(0).get(j) == 1) {
                val = Math.min(val, grid.get(0).get(j));
            }
        }

        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {
                ans.add(1);
            } else {
                ans.add(val);
            }
        }
        return ans;
    }
}
