import java.util.*;

class Solution {
    public List<String> listSort(List<String> lst) {
        // Sort the list first
        Collections.sort(lst);

        // Create a new list to store even-length strings
        List<String> new_lst = new ArrayList<>();

        // Iterate through the sorted list and add even-length strings to the new list
        for (String s : lst) {
            if (s.length() % 2 == 0) {
                new_lst.add(s);
            }
        }

        // Return the sorted list of even-length strings
        return new_lst;
    }
}
