```java
import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> evenOddCount(int num) {
        List<Integer> result = new ArrayList<>();
        int evenCount = 0;
        int oddCount = 0;

        // Convert the number to its absolute value
        num = Math.abs(num);

        // Iterate through each digit of the number
        while (num > 0) {
            int digit = num % 10; // Get the last digit
            if (digit % 2 == 0) {
                evenCount++; // Increment even count
            } else {
                oddCount++; // Increment odd count
            }
            num /= 10; // Remove the last digit
        }

        // Add the counts to the result list
        result.add(evenCount);
        result.add(oddCount);

        return result;
    }
}
