from collections import defaultdict

def check_occurrences(tuples_list):
    """
    Write a function that takes in a list of tuples and returns a dictionary mapping each unique tuple to the number of times it occurs in the list.
    """
    occurrences = defaultdict(int)
    for tup in tuples_list:
        occurrences[tup] += 1
    return dict(occurrences)

# Tests:
assert check_occurrences([(3, 1), (1, 3), (2, 5), (5, 2), (6, 3)]) == {(3, 1): 1, (1, 3): 1, (2, 5): 1, (5, 2): 1, (6, 3): 1}
assert check_occurrences([(4, 2), (2, 4), (3, 6), (6, 3), (7, 4)]) == {(4, 2): 1, (2, 4): 1, (3, 6): 1, (6, 3): 1, (7, 4): 1}
assert check_occurrences([(13, 2), (11, 23), (12, 25), (25, 12), (16, 23)]) == {(13, 2): 1, (11, 23): 1, (12, 25): 1, (25, 12): 1, (16, 23): 1}
