```python
from typing import List

def max_sum(arr: List[int]) -> int:
    n = len(arr)

    # Initialize two arrays to store the maximum sum till each index from left and right
    lis = [arr[i] for i in range(n)]
    lds = [arr[i] for i in range(n)]

    # Compute maximum sum increasing subsequence for all indices
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + arr[i]:
                lis[i] = lis[j] + arr[i]

    # Compute maximum sum decreasing subsequence for all indices
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and lds[i] < lds[j] + arr[i]:
                lds[i] = lds[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        max_sum_bitonic = max(max_sum_bitonic, lis[i] + lds[i] - arr[i])

    return max_sum_bitonic
```

```python
from typing import List

def max_sum_increasing_subseq(arr: List[int], n: int, i: int, k: int) -> int:
    # Initialize a list to store the maximum sum increasing subsequence ending at each index
    dp = [arr[i] for _ in range(n)]

    # Iterate through the array to fill the dp array
    for j in range(i + 1, n):
        if arr[j] > arr[i]:
            dp[j] = max(dp[j], dp[i] + arr[j])

    # Include the kth element if it is greater than the i-th element
    if k > i and arr[k] > arr[i]:
        dp[k] = max(dp[k], dp[i] + arr[k])

    # The result is the maximum value in the dp array
    return max(dp)
```

