import java.util.*;
import java.lang.*;

class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        List<Integer> result = new ArrayList<>(l);
        List<Integer> thirdElements = new ArrayList<>();

        // Extract elements at indices divisible by three
        for (int i = 0; i < result.size(); i += 3) {
            thirdElements.add(result.get(i));
        }

        // Sort the extracted elements
        Collections.sort(thirdElements);

        // Place the sorted elements back into their original positions
        for (int i = 0, j = 0; i < result.size(); i += 3, j++) {
            result.set(i, thirdElements.get(j));
        }

        return result;
    }
}
