```java
import java.util.*;
import java.lang.*;

class Solution {
    public int primeFib(int n) {
        boolean[] isPrime = new boolean[10000]; // Assuming the upper limit for n is 10000
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;

        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i < isPrime.length; i++) {
            if (isPrime[i]) {
                primes.add(i);
                for (int j = i * i; j < isPrime.length; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        List<Integer> fibPrimes = new ArrayList<>();
        int a = 0, b = 1;
        while (fibPrimes.size() < n) {
            int next = a + b;
            a = b;
            b = next;
            if (isPrime[next]) {
                fibPrimes.add(next);
            }
        }

        return fibPrimes.get(fibPrimes.size() - 1);
    }
}
```

