class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        List<Integer> res = new ArrayList<>();
        boolean switchMin = true;
        while (!lst.isEmpty()) {
            int selectedValue = switchMin ? Collections.min(lst) : Collections.max(lst);
            res.add(selectedValue);
            lst.remove(Integer.valueOf(selectedValue));
            switchMin = !switchMin;
        }
        return res;
    }
}
