```java
import java.util.*;
import java.lang.*;

class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();

        for (int i = 0; i < lst.size(); i++) {
            List<Integer> row = lst.get(i);
            for (int j = 0; j < row.size(); j++) {
                if (row.get(j) == x) {
                    List<Integer> coord = new ArrayList<>();
                    coord.add(i);
                    coord.add(j);
                    result.add(coord);
                }
            }
        }

        // Sort by rows in ascending order
        Collections.sort(result, Comparator.comparingInt(a -> a.get(0)));

        // Sort by columns in descending order within the same row
        for (List<Integer> coord : result) {
            Collections.sort(coord, Collections.reverseOrder());
        }

        return result;
    }
}
