```java
import java.util.*;
import java.lang.*;

class Solution {
    public String encode(String message) {
        String vowels = "aeiouAEIOU";
        Map<Character, Character> vowelsReplace = new HashMap<>();
        for (char v : vowels.toCharArray()) {
            vowelsReplace.put(v, (char)(v + 2));
        }

        StringBuilder encodedMessage = new StringBuilder();
        for (char c : message.toCharArray()) {
            if (vowels.indexOf(c) != -1) {
                encodedMessage.append(vowelsReplace.get(c));
            } else {
                encodedMessage.append(c);
            }
        }

        return encodedMessage.toString().toUpperCase().replace('A', 'a').replace('E', 'e').replace('I', 'i').replace('O', 'o').replace('U', 'u');
    }
}
