```java
import java.util.*;
import java.lang.*;

class Solution {
    public String roundedAvg(int n, int m) {
        if (m < n) {
            return "-1";
        }
        long summation = 0;
        for (int i = n; i <= m; i++) {
            summation += i;
        }
        double average = (double) summation / (m - n + 1);
        long roundedAverage = Math.round(average);
        return "0b" + Long.toBinaryString(roundedAverage);
    }
}
