```java
import java.util.*;
import java.lang.*;

class Solution {
    public List<String> bf(String planet1, String planet2) {
        String[] planetNames = {"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"};
        List<String> result = new ArrayList<>();

        int planet1Index = -1;
        int planet2Index = -1;

        for (int i = 0; i < planetNames.length; i++) {
            if (planetNames[i].equals(planet1)) {
                planet1Index = i;
            }
            if (planetNames[i].equals(planet2)) {
                planet2Index = i;
            }
        }

        if (planet1Index == -1 || planet2Index == -1 || planet1Index == planet2Index) {
            return result;
        }

        if (planet1Index < planet2Index) {
            for (int i = planet1Index + 1; i < planet2Index; i++) {
                result.add(planetNames[i]);
            }
        } else {
            for (int i = planet2Index + 1; i < planet1Index; i++) {
                result.add(planetNames[i]);
            }
        }

        return result;
    }
}
