class Solution {
    public List<String> listSort(List<String> lst) {
        Collections.sort(lst);
        List<String> new_lst = new ArrayList<>();
        for (String i : lst) {
            if (i.length() % 2 == 0) {
                new_lst.add(i);
            }
        }
        new_lst.sort(Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));
        return new_lst;
    }
