class Solution {
    public List<Integer> evenOddCount(int num) {
        int even_count = 0;
        int odd_count = 0;
        for (char c : String.valueOf(Math.abs(num)).toCharArray()) {
            if ((c - '0') % 2 == 0) {
                even_count += 1;
            } else {
                odd_count += 1;
            }
        }
        return Arrays.asList(even_count, odd_count);
    }
}
